window.RESIT_EXAMS = [{"id": "A", "title": "Aunt Margaret's Surprise Party · The lost lab notebook · The St Aldhelm's Atlas", "sections": [{"id": "nonfinite", "title": "Non-finite verb forms", "short": "Non-finites", "kind": "type", "width": "", "instruction": "Put the verbs in brackets into the correct non-finite verb form. Add a preposition when necessary.", "paras": ["For months my cousin Harriet had been planning a surprise party for Aunt Margaret's seventieth birthday. Aunt Margaret had a nose for secrets, so Harriet made all of us {{G1}} not to breathe a word. My brother Tom suggested {{G2}} the party in the village hall, but Harriet had her heart set on the old family farmhouse.", "Unfortunately, the farmhouse had stood empty since spring, and the front door badly needed {{G3}}. Harriet insisted {{G4}} most of the work herself, although she had hardly ever held a paintbrush. She even forgot {{G5}} any paint remover, so for a whole week she went around with green hands.", "Keeping the secret was harder than expected. One Sunday Aunt Margaret rang, and Tom chatted happily with her about the weather until she suddenly asked why the family was so busy these days. Tom, a hopeless liar, pretended {{G6}} the question and simply went on {{G7}} about rain and sunshine for another ten minutes.", "A week before the party, Aunt Margaret drove past the farmhouse and noticed Harriet {{G8}} with an enormous cake box on the doorstep. When she pulled over to ask what was going on, Harriet nearly dropped the box, but she managed {{G9}} a story about a colleague's retirement.", "On the big day, forty relatives crowded into the dark kitchen. The plan was simple: the moment Aunt Margaret came through the back door, we would all burst out {{G10}}. When the door finally opened, however, in stepped the postman, who had found it unlocked and wanted to leave a parcel on the table. The lights went on, forty voices sang 'Happy Birthday', and the poor man almost fainted. He had clearly not expected {{G11}} by a crowd of singing strangers. Red in the face, he apologised {{G12}} and hurried out.", "Aunt Margaret arrived ten minutes later. She was not used to {{G13}} the centre of attention and just stood in the doorway, speechless. But when she heard about the postman, even she couldn't help {{G14}}.", "Today, two years later, she still claims she had no idea, but she smiles in a way that makes me wonder. To be honest, she seems {{G15}} about the party all along."], "gaps": {"G1": {"cue": "promise", "key": ["promise"], "also": [], "rule": "'make sb do sth' is followed by the infinitive without 'to' (bare infinitive).", "page": "Reader p. 8"}, "G2": {"cue": "hold", "key": ["holding"], "also": [], "rule": "'suggest' is always followed by the gerund, never by the to-infinitive.", "page": "Reader p. 6"}, "G3": {"cue": "paint", "key": ["painting", "to be painted"], "also": [], "rule": "After 'need' the active gerund carries a passive meaning ('needed painting' = 'needed to be painted'); both forms are correct.", "page": "Reader p. 12"}, "G4": {"cue": "do", "key": ["on doing", "upon doing"], "also": [], "rule": "'insist' needs the preposition 'on', and prepositions are followed by the gerund.", "page": "Reader p. 11"}, "G5": {"cue": "buy", "key": ["to buy"], "also": ["about buying"], "rule": "'forget + to-infinitive' means she did not think of it, so the buying never took place (hence the green hands); 'forget + gerund' would refer to a past experience.", "page": "Reader p. 10"}, "G6": {"cue": "not / hear", "key": ["not to hear"], "also": ["not to have heard", "to not hear", "to not have heard"], "rule": "'pretend' is followed by the to-infinitive, and the negation 'not' is placed before 'to'.", "page": "Reader p. 7"}, "G7": {"cue": "talk", "key": ["talking"], "also": [], "rule": "'go on + gerund' means continuing the same activity (Tom was already chatting about the weather); 'go on + to-infinitive' would mean moving on to something new.", "page": "Reader p. 10"}, "G8": {"cue": "struggle", "key": ["struggling"], "also": ["struggle"], "rule": "Perception verb + object + -ing form shows an action in progress (Harriet was still struggling when Aunt Margaret pulled over); the bare infinitive would present the action as complete.", "page": "Reader p. 11"}, "G9": {"cue": "come up with", "key": ["to come up with"], "also": [], "rule": "'manage' is followed by the to-infinitive.", "page": "Reader p. 7"}, "G10": {"cue": "sing", "key": ["singing"], "also": [], "rule": "The expression 'burst out' is followed by the gerund.", "page": "Reader p. 6"}, "G11": {"cue": "be greeted", "key": ["to be greeted"], "also": [], "rule": "'expect' is followed by the to-infinitive; 'by a crowd' shows the postman is the one greeted, so the passive 'to be + past participle' is needed.", "page": "Reader p. 7"}, "G12": {"cue": "intrude", "key": ["for intruding", "for having intruded"], "also": [], "rule": "'apologise' needs the preposition 'for', which is followed by the gerund (the perfect gerund is also correct).", "page": "Reader p. 11"}, "G13": {"cue": "be", "key": ["being"], "also": [], "rule": "In 'be used to' (= be accustomed to) 'to' is a preposition, not the infinitive marker, so the gerund follows.", "page": "Reader p. 12"}, "G14": {"cue": "laugh", "key": ["laughing"], "also": [], "rule": "'can't/couldn't help' is followed by the gerund.", "page": "Reader p. 6"}, "G15": {"cue": "know", "key": ["to have known"], "also": [], "rule": "'seem' takes the to-infinitive; the perfect infinitive is required because the knowing ('all along') lies before the present moment of seeming.", "page": "Reader p. 7"}}}, {"id": "tense", "title": "Tense & aspect", "short": "Tense", "kind": "type", "width": "", "instruction": "Read the text carefully, taking the whole context into account, and fill in the correct verb form (correct tense and correct aspect). Adjust the word order where necessary.", "paras": ["I {{G1}} chemistry at a high school in Ohio for almost thirty years now, but I {{G2}} my first winter at Brayfield College in Vermont as if it were yesterday. My lab partner that year was a cheerful, easy-going boy from Boston – let me think of a name … I {{G3}} him “Gus”, because he would hate to see his real name in print. Gus was brilliant at chemistry, but he {{G4}} late for everything.", "One Thursday night in February, I {{G5}} our final lab report in my dorm room when Gus burst in, pale and breathless. He told me that he {{G6}} our lab notebook on a bench in the chemistry lab that afternoon. Without the notebook we could not finish the report, which was due at nine the next morning.", "“Relax, Gus, you {{G7}} far too dramatic – that’s not like you at all,” I said, although I was nervous myself. “The last shuttle bus to the science building {{G8}} at 11:15, and it’s only five to eleven. If we {{G9}}, we’ll still catch it.”", "We {{G10}} the science building at 11:25, just as an elderly security guard was locking the front door. “Why {{G11}} earlier?” he grumbled. “It’s high time you kids {{G12}} to bed.” Still, he let us in. We searched every bench in the lab, but the notebook was nowhere to be found. At last Gus opened his backpack to look for a flashlight, and there it was. It {{G13}} in his bag ever since lunch! If he {{G14}} there first, we {{G15}} the last shuttle back to the dorms, and we would not have had to walk two miles through the snow.", "At the time, we had no idea that our little adventure {{G16}} a legend in the chemistry department. Gus and I {{G17}} lunch together next Saturday – I booked the table last week – and when I {{G18}} him, I will ask him about that night once more. He will never admit that it was his fault, of course; it would be a miracle if he {{G19}} it, and I {{G20}} on the spot."], "gaps": {"G1": {"cue": "to teach", "key": ["have been teaching", "'ve been teaching", "have taught", "'ve taught"], "also": [], "rule": "Present frame (“now”) + “for almost thirty years” = a period leading up to the present (continuative perfect); the present perfect progressive stresses the ongoing activity, the simple present perfect is equally correct here.", "page": "Reader p. 15"}, "G2": {"cue": "to still remember", "key": ["still remember"], "also": [], "rule": "Narrator’s present comment: “remember” is a state verb (inert cognition), so simple present – no progressive; “still” (indefinite time) goes in mid-position before the simple verb.", "page": "Reader pp. 14, 34–35"}, "G3": {"cue": "to call", "key": ["will call", "'ll call", "shall call"], "also": [], "rule": "The narrator decides at the moment of telling what to call him (“here”) – will/shall-future for a spontaneous decision under the speaker’s control.", "page": "Reader p. 17"}, "G4": {"cue": "to always be", "key": ["was always"], "also": [], "rule": "Habitual past in a past narrative; with “be” as the main verb the frequency adverb comes after was (mid-position = after am/are/is/was/were).", "page": "Reader pp. 15, 34"}, "G5": {"cue": "to type", "key": ["was typing"], "also": [], "rule": "Time inclusion: the typing was already in progress (background action) when the shorter action “burst in” cut in → past progressive + simple past.", "page": "Reader p. 16"}, "G6": {"cue": "to leave", "key": ["had left", "'d left"], "also": [], "rule": "Reported speech after the past reporting verb “told”: his simple past (“I left it there this afternoon”) is backshifted to the past perfect.", "page": "Reader p. 19"}, "G7": {"cue": "to be", "key": ["are being", "'re being"], "also": [], "rule": "“Be” + adjective in the progressive = temporary behaviour: easy-going Gus is only acting dramatically at this moment (limited duration), it is not his character.", "page": "Reader p. 14"}, "G8": {"cue": "to leave", "key": ["leaves"], "also": [], "rule": "Time-table future: a fixed schedule outside the speaker’s control takes the simple present.", "page": "Reader pp. 14, 17"}, "G9": {"cue": "to hurry", "key": ["hurry"], "also": [], "rule": "Probable condition (pattern I): if-clause in the simple present, main clause future I (“we’ll catch”).", "page": "Reader p. 18"}, "G10": {"cue": "to reach", "key": ["reached"], "also": [], "rule": "Narrative past: a completed event in the sequence of the story at a definite time (11:25).", "page": "Reader p. 15"}, "G11": {"cue": "you not to come", "key": ["didn't you come", "did you not come"], "also": [], "rule": "Question about a finished past event → simple past with do-paraphrase and inverted word order (contracted “didn’t” before the subject, full “not” after it).", "page": "Reader pp. 15, 36–37"}, "G12": {"cue": "to go", "key": ["went"], "also": ["were going"], "rule": "Modal past after “it’s high time”: the past form expresses that the action is overdue now, not past time.", "page": "Reader p. 15"}, "G13": {"cue": "to be", "key": ["had been", "'d been"], "also": [], "rule": "Past perfect for real anteriority: the notebook was in the bag before and up to the past point of orientation, the moment of discovery (“there it was”).", "page": "Reader p. 16"}, "G14": {"cue": "to look", "key": ["had looked", "'d looked"], "also": [], "rule": "Impossible condition (pattern III) about the past – he did not look there first: if-clause in the past perfect.", "page": "Reader p. 18"}, "G15": {"cue": "not to miss", "key": ["would not have missed", "wouldn't have missed"], "also": [], "rule": "Impossible condition: main clause in conditional II (would + have + past participle), parallel to the given “would not have had to walk”.", "page": "Reader p. 18"}, "G16": {"cue": "to become", "key": ["would become"], "also": ["was going to become", "was to become"], "rule": "Future in the past: seen from the past point “at the time”, a later event is expressed with would + infinitive (the backshifted future I).", "page": "Reader pp. 17, 19"}, "G17": {"cue": "to have", "key": ["are having"], "also": ["are going to have", "'re going to have", "will be having", "'ll be having"], "rule": "Intention with present arrangement (the table is already booked) → present progressive with future reference.", "page": "Reader pp. 14, 17"}, "G18": {"cue": "to see", "key": ["see"], "also": [], "rule": "Temporal sub-clause (when) with future meaning → simple present, never will.", "page": "Reader p. 14"}, "G19": {"cue": "to ever admit", "key": ["ever admitted"], "also": ["were ever to admit"], "rule": "“He will never admit it” makes the condition improbable → pattern II with the if-clause in the past; “ever” goes in mid-position before the simple verb.", "page": "Reader pp. 18, 34–35"}, "G20": {"cue": "to faint", "key": ["would faint", "'d faint"], "also": [], "rule": "Improbable condition (pattern II): main clause in conditional I (would + infinitive).", "page": "Reader p. 18"}}}, {"id": "relatives", "title": "Relative clauses", "short": "Relatives", "kind": "type", "width": "short", "instruction": "Fill in the correct relative pronoun and a comma when necessary. If a contact clause is a correct form, then it must be chosen and indicated by C.", "paras": ["Every old college has its legends, and at St Aldhelm's in Durham the favourite one concerns a book. I first heard the story from Dr Margaret Pryce{{G1}} has looked after the college library for almost thirty years and knows most of its secrets.", "In the spring of 1989 the library owned just one book {{G2}} could truly be called a treasure: a hand-coloured atlas of the British Isles printed in 1645. It was kept in a locked glass cabinet in the reading room. The cabinet was the responsibility of the librarian of the day, a nervous little man called Mr Hollis, and the only key was the one {{G3}} he wore on a chain round his neck.", "One Monday morning the cabinet was empty. Nothing had been forced, and the key was still hanging round its owner's neck. Suspicion soon fell on a group of six research students, four {{G4}} had spent the entire weekend in the reading room. Mr Hollis{{G5}} nerves had never been strong, took to his bed for a week, while the police questioned everyone {{G6}} he had spoken to on the Saturday and Sunday. Nobody, it seemed, had noticed anything unusual.", "Then, exactly three weeks later, the atlas was back in its cabinet, wrapped in brown paper. Not a single page was damaged{{G7}} astonished the experts who came up from London to examine it. Tucked inside the cover was a note in neat handwriting: 'Sorry. I only wanted to see Durham as it looked in 1645.'", "{{G8}} puzzles Dr Pryce most is not how the book disappeared but why anyone would bring it back. Every October she tells the story to the new students in the Old Library{{G9}} the famous cabinet still stands in a corner. 'I've given up looking for the culprit,' she always says. 'But I'm certain {{G10}} borrowed our atlas loved it more than any of us ever did.'"], "gaps": {"G1": {"cue": "", "key": [", who"], "also": [], "rule": "The proper name Dr Margaret Pryce is already fully identified, so the clause is non-defining (comma); personal antecedent in subject case takes who, and that is impossible in non-defining clauses.", "page": "Reader pp. 27-28"}, "G2": {"cue": "", "key": ["which", "that"], "also": [], "rule": "Defining clause (without it the sentence would claim the library owned only one book), non-personal antecedent, subject case: which or that, no comma, and no contact clause because the pronoun is the subject.", "page": "Reader pp. 27, 29"}, "G3": {"cue": "", "key": ["C"], "also": [], "rule": "'the one he wore' is a defining clause and the pronoun is the object of 'wore', so the zero pronoun (contact clause) is possible and must be chosen; that/which would lose the point.", "page": "Reader p. 29"}, "G4": {"cue": "", "key": ["of whom"], "also": [], "rule": "Partitive relation in a non-defining clause with a personal antecedent (research students): quantifier + of whom ('four of whom'); the comma is already printed before 'four'.", "page": "Reader p. 28"}, "G5": {"cue": "", "key": [", whose"], "also": [], "rule": "Non-defining clause after the proper name Mr Hollis (comma), genitive case ('his nerves'): whose; the closing comma is already printed after 'strong'.", "page": "Reader p. 28"}, "G6": {"cue": "", "key": ["C"], "also": [], "rule": "Defining clause after 'everyone' with the preposition stranded at the end ('spoken to'): prepositional case without a fronted preposition allows the zero pronoun, so C must be chosen; who/whom/that would lose the point.", "page": "Reader p. 29"}, "G7": {"cue": "", "key": [", which"], "also": [], "rule": "Connective clause: which refers to the whole preceding clause (the fact that no page was damaged), not to a single noun, and is always preceded by a comma.", "page": "Reader p. 30"}, "G8": {"cue": "", "key": ["What", "what"], "also": [], "rule": "There is no antecedent: what = 'that which / the thing that' and contains its own antecedent (what-clause as subject of 'is').", "page": "Reader p. 30"}, "G9": {"cue": "", "key": [", where", ", in which"], "also": [], "rule": "The Old Library is a proper name, so the clause is non-defining (comma); with a place antecedent and no stranded preposition, where (= in which) is the relative word.", "page": "Reader pp. 27-28"}, "G10": {"cue": "", "key": ["whoever"], "also": [], "rule": "No antecedent and the meaning is 'the person who / anybody who, it doesn't matter who': whoever, functioning as subject of 'borrowed'.", "page": "Reader p. 30"}}}, {"id": "mc", "title": "Theory & analysis", "short": "Theory MC", "kind": "mc", "questions": [{"q": "In how many of the following sentences is 'to' used as a preposition?\n1. Nobody in the office objected to working late on Fridays.\n2. Our neighbours used to keep chickens in their back garden.\n3. There is no real alternative to taking the early train.\n4. She seems to have forgotten our appointment completely.", "opts": ["1", "2", "3", "4"], "ans": 1, "why": "Only 'objected to working' and 'alternative to taking' contain the preposition 'to', which is why a gerund follows. In 'used to keep' and 'seems to have forgotten', 'to' is the infinitive marker. Trap: don't confuse 'used to do' (past habit) with 'be used to doing'.", "page": "Reader pp. 6, 11–12"}, {"q": "Compare:\n1. From the hill we watched the hot-air balloon rising above the valley.\n2. From the hill we watched the hot-air balloon rise above the valley.\nWhich statement is correct?", "opts": ["There is no difference in meaning; after 'watch' both forms are interchangeable.", "Sentence 1 presents the rise as a complete action; sentence 2 stresses that it was still going on.", "Sentence 1 stresses the action in progress (incomplete); sentence 2 presents the whole action as complete.", "Sentence 2 is incorrect because 'watch' must be followed by the to-infinitive."], "ans": 2, "why": "After verbs of perception, the -ing form stresses that the action was still going on, while the bare infinitive presents the complete action (Reader p. 11: 'felt her hair rise / rising'). Trap: one option swaps the two meanings, and 'watch sb to do' does not exist.", "page": "Reader p. 11"}, {"q": "In which sentence does the gerund have to be replaced by the to-infinitive?", "opts": ["On the long drive to Brighton we stopped buying sandwiches at a village bakery because we were starving.", "I'll never forget hearing my daughter say her first word.", "If the printer jams again, try switching it off and on.", "Do you remember visiting Edinburgh Castle as a child?"], "ans": 0, "why": "They interrupted the drive in order to buy food, so it must be 'stopped to buy' (stop + to-infinitive = stop in order to do; stop + gerund = no longer do). Trap: the other gerunds are correct. forget/remember + gerund refers to a memory of a past event, and try + gerund means doing something as an experiment.", "page": "Reader p. 10"}, {"q": "Which sentence contains an example of the historic present?", "opts": ["The coach to Oxford leaves at 7.45 tomorrow morning.", "Johnson passes to Davies – and Davies shoots!", "Water freezes at zero degrees Celsius.", "My sister tells me you're moving to Leeds next month."], "ans": 3, "why": "The reader counts verbs of communication (tell, hear, understand) as historic present: the telling happened in the past but is reported in the present (Reader p. 14e). Trap: the football commentary is the instantaneous use, 'leaves' is the time-table future and 'freezes' is the unrestrictive use.", "page": "Reader p. 14"}, {"q": "If my grandmother still lived in Cornwall instead of London, we would spend every summer there. – Grammatically speaking, this is", "opts": ["a probable condition.", "an impossible condition, because the grandmother no longer lives in Cornwall.", "an improbable condition.", "a supposition expressed by 'were to'."], "ans": 2, "why": "The reader names the pattern by its forms: past tense in the if-clause + conditional I (would + infinitive) = improbable condition (Reader p. 18). Trap: although the situation is unreal, an impossible condition needs past perfect + conditional II (If she had lived …, we would have spent …).", "page": "Reader p. 18"}, {"q": "Which sentence describes temporary behaviour rather than a permanent characteristic?", "opts": ["My brother is very tidy.", "My brother is being remarkably tidy this week – he must want something.", "My brother has always been a tidy person.", "My brother was a tidy child."], "ans": 1, "why": "'is being + adjective' (progressive) signals limited duration, i.e. behaviour at the moment rather than a character trait (Reader p. 14, present progressive b). Trap: 'be' is usually a state verb, but the progressive is correct when it describes temporary behaviour.", "page": "Reader p. 14"}, {"q": "You needn't have booked a table – the restaurant was almost empty. – What does this sentence tell us?", "opts": ["The person booked a table, but it turned out to be unnecessary.", "The person did not book a table because it was not necessary.", "The person was not allowed to book a table.", "The modal expresses a logical deduction about the past."], "ans": 0, "why": "needn't + perfect infinitive means that the action was done but only later turned out to be unnecessary (Reader p. 24: 'I needn't have gone to class yesterday'). Trap: it does not mean that the table was not booked. The booking did take place.", "page": "Reader p. 24"}, {"q": "Which modal can express concession in the sense of 'I admit that …'?", "opts": ["must", "shall", "had better", "may"], "ans": 3, "why": "Concession is expressed by may: 'He may be young, but he is very wise' (= I admit that he is young …) (Reader p. 23). Trap: must expresses obligation or deduction, shall a promise or offer, and had better strong advice.", "page": "Reader p. 23"}, {"q": "In which sentence can the relative pronoun be left out (contact clause)?", "opts": ["The painting, which my aunt bought in Bath, now hangs in our hall.", "The man who repaired our roof also cleaned the gutters.", "The recipe that Mum got from her neighbour is absolutely delicious.", "My cousin Liam, who you met at the wedding, is visiting next week."], "ans": 2, "why": "A contact clause is only possible in a defining clause where the pronoun is the object or prepositional object: 'The recipe Mum got from her neighbour …' (Reader p. 29). Trap: non-defining clauses (with commas) never allow omission, and in the subject case ('who repaired') the pronoun must stay.", "page": "Reader pp. 28–29"}, {"q": "Our train was delayed by two hours, which meant that we missed the opening speech. – What kind of clause does 'which' introduce here?", "opts": ["A defining relative clause referring to 'two hours'.", "A connective clause referring to the whole preceding main clause.", "A non-defining relative clause referring to 'our train'.", "A what-clause (which = that which)."], "ans": 1, "why": "'which' refers back to the whole statement (the delay as such), so the reader calls this a connective clause (Reader p. 30). Trap: it refers neither to the train nor to the two hours, and 'what' could never be used here.", "page": "Reader p. 30"}, {"q": "Which sentence is correct?", "opts": ["I have three older brothers, that all live in Glasgow.", "I have three older brothers, all of which live in Glasgow.", "I have three older brothers, all of who live in Glasgow.", "I have three older brothers, all of whom live in Glasgow."], "ans": 3, "why": "A partitive relation with a personal antecedent takes all/some/two of + whom (Reader p. 28: 'My sisters, all of whom are red-haired'). Trap: 'which' is for things, a preposition needs 'whom' (not 'who'), and 'that' cannot introduce a non-defining clause.", "page": "Reader p. 28"}, {"q": "In which sentence is the word order NOT correct?", "opts": ["No doubt the parcel will arrive tomorrow.", "Rarely have I eaten such good fish and chips.", "In no time had the children finished their homework.", "Under no circumstances should you open this door."], "ans": 2, "why": "'In no time' is on the reader's list of expressions that do not trigger inversion. The correct form is 'In no time the children had finished their homework' (Reader p. 37). Trap: it looks negative, but only negative or restrictive adverbials like 'rarely' or 'under no circumstances' require inversion; 'no doubt' doesn't either.", "page": "Reader pp. 36–37"}, {"q": "Which word order is correct?", "opts": ["We probably won't finish the project by Friday.", "We won't probably finish the project by Friday.", "We won't finish probably the project by Friday.", "Probably won't we finish the project by Friday."], "ans": 0, "why": "With contracted negatives (won't, don't, can't), the adverb always comes before the auxiliary (Reader p. 35: 'I probably won't be there'). Trap: with uncontracted 'will not' you can also say 'We will probably not finish …', but never 'won't probably'.", "page": "Reader p. 35"}, {"q": "In which sentence is the noun thought of as a particular building rather than as an institution?", "opts": ["Mum went to the school to talk to my class teacher.", "My little brother starts school next September.", "Grandpa spent a week in hospital after his knee operation.", "Our neighbours go to church every Sunday."], "ans": 0, "why": "With the article, 'the school' is the building, which Mum visits for a different purpose (talking to the teacher) (Reader p. 39). Trap: school, hospital and church without an article refer to the institution and its purpose: learning, treatment and worship.", "page": "Reader p. 39"}, {"q": "In which sentence must the gap remain empty (no indefinite article)?", "opts": ["Could you wait ___ few minutes? I'm nearly ready.", "I've already made ___ few friends at my new job, so I don't feel lonely.", "We still have ___ few biscuits left – would you like one?", "The village is so remote that ___ few tourists ever find it."], "ans": 3, "why": "'few' without 'a' has a negative meaning (= hardly any): almost no tourists find the village (Reader p. 40). Trap: the other sentences need 'a few' (= a small number, some) because their meaning is positive.", "page": "Reader pp. 39–40"}]}]}, {"id": "B", "title": "The Trumpet Next Door · Grandad's trunk · The Keeper's Daughter", "sections": [{"id": "nonfinite", "title": "Non-finite verb forms", "short": "Non-finites", "kind": "type", "width": "", "instruction": "Put the verbs in brackets into the correct non-finite verb form. Add a preposition when necessary.", "paras": ["When I moved into my dorm room at a small college in Ohio, I had been looking forward to {{G1}} my new roommate all summer. Marcus turned out to be a friendly music major from Chicago – and a trumpet player who kept {{G2}} until well after midnight.", "At first I didn't mind {{G3}} to his scales; I even found them relaxing. But after two weeks without proper sleep, I seriously considered {{G4}} to another dorm.", "When I finally complained, Marcus was not exactly pleased. The music building closed at ten every night, and he strongly objected {{G5}} to practice in the damp basement of our dorm instead. He also flatly denied {{G6}} anyone awake, although our neighbor across the hall had already threatened {{G7}} us to the resident advisor.", "In the end it was this neighbor, a quiet engineering student named Priya, who saved our friendship. \"Why don't you just try {{G8}} with a mute?\" she asked Marcus one evening. He had never used one, but to his surprise it worked perfectly: the trumpet sounded soft and warm, and I could finally sleep. Soon I even started to enjoy the music. Whenever I came back from class and heard him through our door, I would stop {{G9}} for a minute or two before going in.", "One night in December I heard someone {{G10}} three times at our door. It was Professor Lang from the music department, who lived in the faculty house next door. He had heard Marcus play a piece of his own through the open window and thought it deserved {{G11}} at the winter concert. A week later he had Marcus {{G12}} it for the whole department.", "That spring Marcus succeeded {{G13}} a scholarship to a summer program in New York, and Priya now claims {{G14}} him. Marcus, on the other hand, does not enjoy {{G15}} of his midnight scales – but I still keep a trumpet mute on my desk as a souvenir."], "gaps": {"G1": {"cue": "meet", "key": ["meeting"], "also": [], "rule": "In 'look forward to' the word 'to' is a preposition, so the gerund follows.", "page": "Reader pp. 6, 11"}, "G2": {"cue": "practice", "key": ["practicing", "practising", "on practicing", "on practising"], "also": [], "rule": "'keep (on)' (= continue) is always followed by the gerund.", "page": "Reader p. 6"}, "G3": {"cue": "listen", "key": ["listening"], "also": [], "rule": "'mind' (in negative or interrogative sentences) is followed by the gerund.", "page": "Reader p. 6"}, "G4": {"cue": "move", "key": ["moving"], "also": [], "rule": "'consider' in the sense of 'think about doing' takes the gerund; the to-infinitive only follows in 'consider sb to be' (= regard as).", "page": "Reader p. 10"}, "G5": {"cue": "have", "key": ["to having"], "also": [], "rule": "'object' needs the preposition 'to', which is followed by the gerund ('objected to having to practice').", "page": "Reader p. 11"}, "G6": {"cue": "keep", "key": ["keeping", "having kept"], "also": [], "rule": "'deny' is always followed by the gerund; the perfect gerund is also correct.", "page": "Reader p. 6"}, "G7": {"cue": "report", "key": ["to report"], "also": [], "rule": "'threaten' is followed by the to-infinitive.", "page": "Reader p. 7"}, "G8": {"cue": "play", "key": ["playing"], "also": [], "rule": "'try + gerund' means doing something as an experiment to see if it works (and it did); 'try + to-infinitive' means making an attempt.", "page": "Reader p. 10"}, "G9": {"cue": "listen", "key": ["to listen"], "also": [], "rule": "'stop + to-infinitive' means interrupting one activity (walking to class) in order to do another; 'stop listening' would mean no longer listening.", "page": "Reader p. 10"}, "G10": {"cue": "knock", "key": ["knock"], "also": ["knocking"], "rule": "Perception verb + object + bare infinitive presents a complete action (three knocks, then it was over); the -ing form would stress an action in progress.", "page": "Reader p. 11"}, "G11": {"cue": "perform", "key": ["performing", "to be performed"], "also": [], "rule": "After 'deserve' the active gerund carries a passive meaning ('deserved performing' = 'deserved to be performed'); both forms are correct.", "page": "Reader p. 12"}, "G12": {"cue": "play", "key": ["play"], "also": [], "rule": "'have sb do sth' is followed by the bare infinitive.", "page": "Reader p. 8"}, "G13": {"cue": "win", "key": ["in winning"], "also": [], "rule": "'succeed' needs the preposition 'in', which is followed by the gerund.", "page": "Reader p. 11"}, "G14": {"cue": "discover", "key": ["to have discovered"], "also": [], "rule": "'claim' takes the to-infinitive; the perfect infinitive is required because the discovering happened before her present claim.", "page": "Reader p. 7"}, "G15": {"cue": "be reminded", "key": ["being reminded"], "also": [], "rule": "'enjoy' is always followed by the gerund; since Marcus is the one reminded, the passive gerund 'being + past participle' is needed (cf. 'They enjoy being praised').", "page": "Reader p. 6"}}}, {"id": "tense", "title": "Tense & aspect", "short": "Tense", "kind": "type", "width": "", "instruction": "Read the text carefully, taking the whole context into account, and fill in the correct verb form (correct tense and correct aspect). Adjust the word order where necessary.", "paras": ["Every family {{G1}} its secrets, I suppose, and ours was hidden in a battered leather trunk in my grandparents’ attic in Whitby. I {{G2}} you how my cousin Rosie and I discovered it one rainy August afternoon in 1998. Grandad was a strict and rather quiet retired bank manager, and before that afternoon nobody in the family {{G3}} to open his trunk.", "When we crept up the attic stairs, the grown-ups {{G4}} cards in the kitchen. The trunk was locked, but Rosie poked at the lock with a hairpin until it {{G5}} way with a soft click. Inside, wrapped in tissue paper, {{G6}} a pair of black dancing shoes and a silver cup engraved “Northern Tango Champion 1958”. Little did we know that a few minutes later, when we turned round, Grandad himself {{G7}} in the doorway.", "For a long moment he just stared at the shoes. Then he asked quietly, “{{G8}} you’re up here?”", "“You {{G9}} very mysterious all of a sudden, Grandad,” said Rosie. “Whose cup is this?”", "He went red, and then, to our amazement, he burst out laughing. I still wish I {{G10}} a photo of his face from that moment! The cup was his, he admitted, and he promised that he {{G11}} everything to Grandma himself after supper.", "“If I {{G12}} twenty years younger, I {{G13}} you a few steps right now,” he sighed. “And if you two {{G14}} that trunk, I {{G15}} anyone about my dancing days. Now, not a word to anyone until I {{G16}} ready. If you keep quiet, I {{G17}} you the biggest ice creams in Whitby tomorrow. Your train back to London {{G18}} until four, so there’s plenty of time.”", "Grandad is ninety-one now. He and Grandma {{G19}} tango classes at the village hall since 2020, and Grandma {{G20}} his “secret past” hilarious."], "gaps": {"G1": {"cue": "to have", "key": ["has"], "also": [], "rule": "Narrator’s general present comment (unrestrictive use); “have” in the sense of possession is a state verb and stays simple.", "page": "Reader p. 14"}, "G2": {"cue": "to tell", "key": ["will tell", "'ll tell", "shall tell"], "also": ["am going to tell", "'m going to tell"], "rule": "The narrator decides now, while speaking, to tell the story – will/shall-future for a spontaneous decision.", "page": "Reader p. 17"}, "G3": {"cue": "to ever dare", "key": ["had ever dared"], "also": [], "rule": "Past perfect: anteriority to the past point of orientation “that afternoon” (“before that afternoon”); “ever” goes after the first auxiliary.", "page": "Reader pp. 16, 34"}, "G4": {"cue": "to still play", "key": ["were still playing"], "also": [], "rule": "Time inclusion: the card game was already in progress (background) when we crept upstairs → past progressive; “still” after the first auxiliary.", "page": "Reader pp. 16, 34"}, "G5": {"cue": "to give", "key": ["gave"], "also": [], "rule": "Narrative past: a completed event in the story sequence (give – gave – given).", "page": "Reader p. 15"}, "G6": {"cue": "to lie", "key": ["lay"], "also": [], "rule": "Narrative past of intransitive “lie” (lie – lay – lain), not “laid” (from transitive “lay”); after the place adverbial “Inside” the subject simply follows the verb.", "page": "Reader p. 15"}, "G7": {"cue": "to stand", "key": ["would be standing"], "also": [], "rule": "Future in the past + progressive: seen from the past moment, Grandad’s standing in the doorway would be in progress a few minutes later (would be + -ing, the backshifted future progressive).", "page": "Reader pp. 17, 19"}, "G8": {"cue": "your grandmother to know", "key": ["Does your grandmother know", "does your grandmother know"], "also": [], "rule": "Present question about a state: “know” is a state verb (simple present), and a simple verb form needs the do-paraphrase for the inverted question order.", "page": "Reader pp. 14, 36–37"}, "G9": {"cue": "to be", "key": ["are being", "'re being"], "also": [], "rule": "“Be” + adjective in the progressive = temporary behaviour: Grandad is acting mysteriously at this moment (limited duration).", "page": "Reader p. 14"}, "G10": {"cue": "to have", "key": ["had"], "also": [], "rule": "Modal past after “I wish” for an unreal present wish – the narrator has no such photo now.", "page": "Reader p. 15"}, "G11": {"cue": "to explain", "key": ["would explain", "'d explain"], "also": ["was going to explain"], "rule": "Reported speech: his “I will explain …” after the past reporting verb “promised” becomes conditional I (would + infinitive).", "page": "Reader p. 19"}, "G12": {"cue": "to be", "key": ["were"], "also": ["was"], "rule": "Improbable condition (pattern II): if-clause in the past; in hypothetical meaning “were” is used for all persons, including I.", "page": "Reader pp. 16, 18"}, "G13": {"cue": "to show", "key": ["would show", "'d show"], "also": [], "rule": "Pattern II main clause: conditional I (would + infinitive).", "page": "Reader p. 18"}, "G14": {"cue": "not to open", "key": ["hadn't opened", "had not opened"], "also": [], "rule": "Impossible condition about the past (they did open the trunk): if-clause in the past perfect.", "page": "Reader p. 18"}, "G15": {"cue": "to never tell", "key": ["would never have told", "'d never have told"], "also": ["would have never told"], "rule": "Pattern III main clause: conditional II (would + have + past participle); with compound verbs “never” normally follows the first auxiliary.", "page": "Reader pp. 18, 34"}, "G16": {"cue": "to be", "key": ["am", "'m"], "also": [], "rule": "Temporal sub-clause (until) with future meaning → simple present, never will.", "page": "Reader p. 14"}, "G17": {"cue": "to buy", "key": ["will buy", "'ll buy", "shall buy"], "also": ["am going to buy", "'m going to buy"], "rule": "Probable condition (pattern I): if-clause in the simple present (“keep”), main clause future I.", "page": "Reader p. 18"}, "G18": {"cue": "not to leave", "key": ["doesn't leave", "does not leave"], "also": [], "rule": "Time-table future: a fixed train schedule takes the simple present, negated with the do-paraphrase.", "page": "Reader pp. 14, 17"}, "G19": {"cue": "to attend", "key": ["have been attending", "have attended"], "also": [], "rule": "Present frame (“now”) + “since 2020” = repeated activity in a period leading up to the present → present perfect progressive; the simple present perfect (habit up to now) is equally correct.", "page": "Reader p. 15"}, "G20": {"cue": "to still find", "key": ["still finds"], "also": [], "rule": "Narrator’s present: “find” (= consider) is a verb of inert cognition, so simple present – no progressive; “still” in mid-position before the simple verb.", "page": "Reader pp. 14, 35"}}}, {"id": "relatives", "title": "Relative clauses", "short": "Relatives", "kind": "type", "width": "short", "instruction": "Fill in the correct relative pronoun and a comma when necessary. If a contact clause is a correct form, then it must be chosen and indicated by C.", "paras": ["Anyone driving north along the Wisconsin shore of Lake Michigan will sooner or later notice the Harbor Bend Light{{G1}} has guarded the entrance to a small fishing harbor since 1871. Its first keeper was a Swedish immigrant named Anders Lindqvist, but it was his daughter Ingrid {{G2}} made the lighthouse famous.", "Ingrid was the only child in Harbor Bend {{G3}} bedroom window looked straight out over open water, and by the age of ten she could trim a wick as neatly as her father. In 1883, the year {{G4}} she turned thirteen, Anders fell ill, and for the next two winters Ingrid climbed the ninety-six steps every evening to light the lamp herself.", "It was demanding work. Any ship {{G5}} strayed too close to the point risked running onto a hidden sandbar, so the lamp had to burn from dusk to dawn without fail. Ingrid kept careful logbooks, several {{G6}} are now on display in the town museum. They record the weather, the passing ships and the amount of oil used each night.", "Her finest hour came in November 1886{{G7}} a sudden blizzard caught the town's fishing fleet out on the lake. With the snow too thick for anyone to see the lamp, Ingrid rang the fog bell for nine hours without a break, so that the fishermen had something {{G8}} they could steer by. Every boat made it safely back into the harbor{{G9}} earned her a gold watch from the grateful townspeople.", "The lighthouse was automated in 1939 and is now a museum. In summer, visitors can join {{G10}} of the two daily tours suits them best: the 'Keeper's Climb' up the tower or the 'Lakeshore Walk' along the rocks below."], "gaps": {"G1": {"cue": "", "key": [", which"], "also": [], "rule": "The Harbor Bend Light is a proper name, so the clause is non-defining (comma); non-personal antecedent in subject case takes which, never that.", "page": "Reader pp. 27-28"}, "G2": {"cue": "", "key": ["who", "that"], "also": [], "rule": "Cleft sentence 'it was ... who': the clause is defining (no comma) and the pronoun is the subject of 'made', so who or that, and no contact clause in subject case.", "page": "Reader p. 29"}, "G3": {"cue": "", "key": ["whose"], "also": [], "rule": "'the only child' requires a defining clause (no comma); genitive case ('her bedroom window') with a personal antecedent: whose.", "page": "Reader p. 29"}, "G4": {"cue": "", "key": ["C"], "also": [], "rule": "After the time noun 'the year' the defining clause can be a contact clause ('the year she turned thirteen'); when/in which are grammatical but the task demands C whenever a contact clause is correct (cf. 'the day C Hale-Bopp...' in the July exam).", "page": "Reader pp. 27, 29"}, "G5": {"cue": "", "key": ["which", "that"], "also": [], "rule": "'Any ship' needs a defining clause (no comma) to say which ships were in danger; non-personal antecedent in subject case: which or that, no contact clause.", "page": "Reader p. 29"}, "G6": {"cue": "", "key": ["of which"], "also": [], "rule": "Partitive relation in a non-defining clause with a non-personal antecedent (logbooks): quantifier + of which ('several of which'); the comma is already printed before 'several'.", "page": "Reader p. 28"}, "G7": {"cue": "", "key": [", when", ", in which"], "also": [], "rule": "November 1886 is a specific, already identified point in time, so the clause is non-defining and needs a comma; the time relative is when.", "page": "Reader pp. 27-28"}, "G8": {"cue": "", "key": ["C"], "also": [], "rule": "Defining clause after 'something' with the preposition stranded at the end ('steer by'): prepositional case without fronted preposition allows the zero pronoun, so C must be chosen; that/which would lose the point.", "page": "Reader p. 29"}, "G9": {"cue": "", "key": [", which"], "also": [], "rule": "Connective clause: which refers to the whole preceding clause (the fact that every boat got back safely), not to 'harbor', and takes a comma.", "page": "Reader p. 30"}, "G10": {"cue": "", "key": ["whichever"], "also": [], "rule": "No antecedent and a choice between a limited set of things ('of the two daily tours'): whichever = 'it doesn't matter which (one)', subject of 'suits'.", "page": "Reader pp. 30-31"}}}, {"id": "mc", "title": "Theory & analysis", "short": "Theory MC", "kind": "mc", "questions": [{"q": "In which of the following sentences is 'to' NOT used as a preposition?", "opts": ["After a year in Seattle, Hannah has got used to carrying an umbrella everywhere.", "My uncle has a strong objection to paying for parking.", "We are determined to finish the renovation before Christmas.", "I'm really looking forward to meeting your parents."], "ans": 2, "why": "'be determined to do' takes the to-infinitive, so 'to' is the infinitive marker here (Reader p. 12). Trap: 'get used to', 'objection to' and 'look forward to' contain the preposition 'to' and are therefore followed by the gerund.", "page": "Reader pp. 6, 12"}, {"q": "Which sentence contains an INCORRECT non-finite verb form?", "opts": ["The doctor advised taking a short walk after every meal.", "Our landlord doesn't permit to keep pets in the flat.", "The doctor advised him to take a short walk after every meal.", "Our landlord doesn't permit tenants to keep pets in the flat."], "ans": 1, "why": "Verbs of authority (advise, allow, permit, forbid …) take the gerund when there is no personal object and the to-infinitive after such an object (Reader p. 9). Correct forms are 'doesn't permit keeping pets' or 'doesn't permit tenants to keep pets'.", "page": "Reader p. 9"}, {"q": "Which sentence expresses a conclusion based on present evidence?", "opts": ["The film starts at 8.15 tonight.", "I'm meeting Sophie outside the cinema at eight – we booked the tickets yesterday.", "– The popcorn's all gone. – Don't worry, I'll get some more.", "Look at that queue! We're going to miss the start of the film."], "ans": 3, "why": "The going to-future with events that depend on external circumstances expresses a conclusion based on evidence, here the queue you can see now (Reader p. 17). Trap: 'starts' is the time-table future, 'I'm meeting' an intention with present arrangement, and 'I'll get' a spontaneous decision.", "page": "Reader p. 17"}, {"q": "Which sentence contains an example of the modal past?", "opts": ["It's high time the landlord fixed the heating.", "Yesterday I finally finished my essay on Dickens.", "When I was a student, I cycled to campus every day.", "The ship docked at Southampton and the passengers went ashore."], "ans": 0, "why": "After 'it is high time' (like 'as if' or 'if only'), the past tense has hypothetical meaning: the heating has not been fixed yet (Reader p. 15d). Trap: the other sentences refer to real past events (unitary, habitual and narrative past).", "page": "Reader p. 15"}, {"q": "If you should see Mr Patel at the meeting, give him this envelope. – The if-clause with 'should'", "opts": ["expresses an obligation: you are required to see Mr Patel.", "expresses improbability: the speaker does not really expect you to see him.", "expresses politeness or willingness.", "is incorrect, because 'should' cannot be used in an if-clause."], "ans": 1, "why": "An if-clause with should + imperative (or future I) in the main clause expresses improbability (Reader p. 18: 'If he should call, tell him to wait.'). Trap: this 'should' has nothing to do with obligation, and politeness or willingness is expressed by will/would in the if-clause.", "page": "Reader p. 18"}, {"q": "Every Sunday morning, my grandfather would walk down to the harbour to watch the fishing boats come in. – Here 'would' expresses", "opts": ["a polite request.", "a hypothetical action (conditional I).", "a characteristic habit in the past.", "the future seen from the past (backshifted 'will')."], "ans": 2, "why": "would expresses a characteristic, typical activity in the past, and 'every Sunday morning' marks the repeated habit (Reader p. 23). Trap: there is no condition, so it is not conditional I, and nothing is being reported.", "page": "Reader p. 23"}, {"q": "In how many of the following sentences does the modal express a logical deduction?\n1. You've been travelling all day – you must be exhausted.\n2. Visitors must sign in at reception.\n3. He failed the driving test twice; he can't have practised much.\n4. You should apologise to your sister.", "opts": ["1", "2", "3", "4"], "ans": 1, "why": "Only sentence 1 (must = deduction from present evidence) and sentence 3 (can't have = negative deduction about the past) judge likelihood (Reader p. 21). Trap: 'Visitors must sign in' is an obligation and 'should apologise' a recommendation. Both are intrinsic, not extrinsic modality.", "page": "Reader pp. 21–22"}, {"q": "When Clara first sat next to Tom in the school orchestra, she had no idea that he was to become her husband. – 'was to' expresses", "opts": ["'fate': a later event known to the speaker now but still unknown to Clara at the time.", "an order given to Tom.", "an official plan or arrangement.", "a supposition or rumour."], "ans": 0, "why": "be to can express 'fate': looking back from the present, the speaker knows what happened, but the person in the story did not know it yet (Reader p. 23). Trap: be to also expresses orders and formal plans, but 'she had no idea' points to fate.", "page": "Reader p. 23"}, {"q": "Compare:\n1. My sister who lives in Canada is a nurse.\n2. My sister, who lives in Canada, is a nurse.\nWhich statement is correct?", "opts": ["Both sentences imply that the speaker has only one sister.", "Sentence 1 implies that the speaker has only one sister; sentence 2 implies that there are several.", "Sentence 2 is incorrect because 'who' cannot introduce a non-defining clause.", "Sentence 1 implies that the speaker has more than one sister; sentence 2 implies that there is only one."], "ans": 3, "why": "The defining clause in sentence 1 identifies which sister is meant (the one in Canada, as opposed to the others); the non-defining clause in sentence 2 only adds information about the one sister (Reader p. 27). Trap: the commas change the meaning, so they are not just punctuation.", "page": "Reader p. 27"}, {"q": "In which sentence is 'that' used correctly?", "opts": ["The village, that lies at the foot of the hill, is famous for its cheese.", "This is the drawer in that I keep the spare keys.", "The neighbour that helped us move the piano refused to take any money.", "She passed her driving test at the first attempt, that surprised everyone."], "ans": 2, "why": "'that' is fine in a defining clause, also with a personal antecedent (Reader p. 29: 'The man that is standing next to the door'). Trap: 'that' is impossible in non-defining and connective clauses (use 'which') and directly after a preposition ('in which').", "page": "Reader pp. 28–30"}, {"q": "Which word order is correct?", "opts": ["Little the tourists knew that the castle was closed on Mondays.", "Little did the tourists know that the castle was closed on Mondays.", "Little knew the tourists that the castle was closed on Mondays.", "Little did the tourists knew that the castle was closed on Mondays."], "ans": 1, "why": "Fronted negative 'little' requires inversion, and with a simple verb form (knew) you need the do-paraphrase: did + subject + infinitive (Reader p. 37). Trap: after 'did', the main verb is in the infinitive, not the past tense.", "page": "Reader pp. 36–37"}, {"q": "Which of the following exclamations has the correct word order?", "opts": ["Here comes it!", "Back went they to their seats!", "Off go we!", "Out ran the children into the snow!"], "ans": 3, "why": "After here, there, up, out, back, off and similar adverbials, the verb comes before a noun subject ('Out ran the children') (Reader p. 37). Trap: a pronoun subject keeps the normal order: Here it comes! Back they went! Off we go!", "page": "Reader p. 37"}, {"q": "Surprisingly, the old ferry still runs twice a day. – 'Surprisingly' is", "opts": ["a comment adverb, normally in front position.", "an adverb of manner, normally in end position.", "a connecting adverb, normally in mid position.", "an adverb of degree, normally in mid position."], "ans": 0, "why": "surprisingly, fortunately and naturally are comment adverbs that express the speaker's view, and they normally go in front position (Reader pp. 33, 35). Trap: not every -ly adverb is an adverb of manner; this one does not describe how the ferry runs.", "page": "Reader pp. 33, 35"}, {"q": "In 1998 she was elected ___ Mayor of Chester, a post she held for six years. – Which is correct?", "opts": ["'a', because 'Mayor' is the name of a profession.", "'the', because 'Mayor' is followed by an of-phrase.", "no article, because this is a unique position.", "'a', because 'Mayor' is a countable noun."], "ans": 2, "why": "Unique positions and titles take no article: 'He was appointed Head Librarian' (Reader p. 39). Trap: the of-phrase does not make the article necessary. The July exam key also marked 'the Head of the Department' as wrong.", "page": "Reader p. 39"}, {"q": "In which sentence must the indefinite article be added?", "opts": ["After the long hike, Grandma served us ___ enormous breakfast.", "We usually have ___ lunch in the canteen on Mondays.", "The old windows are made of ___ glass.", "Could you give me ___ advice about my CV?"], "ans": 0, "why": "Meals take no article unless an adjective comes before them: 'an enormous breakfast' (Reader p. 40). Trap: materials (glass) and uncountable nouns (advice) never take a/an.", "page": "Reader p. 40"}]}]}, {"id": "C", "title": "The Millbrook Rooster · The phantom pianist · Grandma Rosa's Pie", "sections": [{"id": "nonfinite", "title": "Non-finite verb forms", "short": "Non-finites", "kind": "type", "width": "", "instruction": "Put the verbs in brackets into the correct non-finite verb form. Add a preposition when necessary.", "paras": ["For over a hundred years, a copper rooster had turned with the wind on the roof of the town museum in Millbrook, Vermont, and nobody in town could imagine {{G1}} without it. So when Mrs. Patterson, who lived across the street, opened her curtains one Monday morning in June, she could hardly believe her eyes: the rooster was gone. She vaguely remembered {{G2}} a figure {{G3}} up a ladder around midnight – just for a second, before a cloud covered the moon.", "The museum director, Mr. Hollis, was in despair. Calling the state police would mean {{G4}} that the town's most famous treasure had disappeared under his nose, and he would rather {{G5}} for it himself than face the newspapers.", "For three days he went from door to door. He was especially interested {{G6}} to anyone who owned a ladder long enough to reach the roof. The trail soon led to Walter Briggs, the museum's retired caretaker, who lived alone at the edge of town. When Mr. Hollis knocked, Walter failed {{G7}} him in the eye, and after a long silence he led him to his barn.", "There, under an old blanket, lay the rooster. The copper had turned green and black, the tail was bent, and the whole bird badly needed {{G8}}. Walter explained that for years he had asked the town council to have the rooster repaired, but the council had always refused {{G9}} money on it. In the end he had given up {{G10}} for their permission and decided to do the job himself. He had not wanted {{G11}} by anyone, so he had chosen a cloudy night. Walter apologized {{G12}} so much worry, and Mr. Hollis, who had prepared an angry speech, simply shook his hand.", "Two weeks later, on Founders' Day, the rooster was back on the roof, shining like new, and when it caught the first breeze, the whole crowd began {{G13}}. Walter received a medal from the mayor, although he has still not gotten used to {{G14}} a hero. Today, more than ten years later, the rooster still turns above Main Street and appears {{G15}} none of its old charm."], "gaps": {"G1": {"cue": "live", "key": ["living"], "also": [], "rule": "'imagine' is always followed by the gerund.", "page": "Reader p. 6"}, "G2": {"cue": "see", "key": ["seeing", "having seen"], "also": [], "rule": "'remember + gerund' refers to a memory of something that happened in the past; 'remember + to-infinitive' means not forgetting a duty.", "page": "Reader p. 10"}, "G3": {"cue": "climb", "key": ["climbing"], "also": ["climb"], "rule": "Perception verb + object + -ing form: she saw the action only in progress ('just for a second'), not as a complete action, which the bare infinitive would express.", "page": "Reader p. 11"}, "G4": {"cue": "admit", "key": ["admitting"], "also": [], "rule": "'mean + gerund' = involve / have as a consequence; 'mean + to-infinitive' would mean 'intend'.", "page": "Reader p. 10"}, "G5": {"cue": "search", "key": ["search"], "also": [], "rule": "'would rather' is followed by the bare infinitive (as is 'than face').", "page": "Reader p. 8"}, "G6": {"cue": "talk", "key": ["in talking"], "also": [], "rule": "'be interested' needs the preposition 'in', which is followed by the gerund.", "page": "Reader p. 11"}, "G7": {"cue": "look", "key": ["to look"], "also": [], "rule": "'fail' is followed by the to-infinitive.", "page": "Reader p. 7"}, "G8": {"cue": "clean", "key": ["cleaning", "to be cleaned"], "also": [], "rule": "After 'need' the active gerund carries a passive meaning ('needed cleaning' = 'needed to be cleaned'); both forms are correct.", "page": "Reader p. 12"}, "G9": {"cue": "spend", "key": ["to spend"], "also": [], "rule": "'refuse' is followed by the to-infinitive.", "page": "Reader p. 7"}, "G10": {"cue": "wait", "key": ["waiting"], "also": [], "rule": "'give up' is always followed by the gerund.", "page": "Reader p. 6"}, "G11": {"cue": "be seen", "key": ["to be seen"], "also": [], "rule": "'want' (= wish) takes the to-infinitive; 'by anyone' shows Walter is the one seen, so the passive 'to be + past participle' is needed.", "page": "Reader p. 7"}, "G12": {"cue": "cause", "key": ["for causing", "for having caused"], "also": [], "rule": "'apologize' needs the preposition 'for', which is followed by the gerund (the perfect gerund is also correct).", "page": "Reader p. 11"}, "G13": {"cue": "cheer", "key": ["cheering", "to cheer"], "also": [], "rule": "'begin' can be followed by the gerund or the to-infinitive without a change in meaning.", "page": "Reader p. 9"}, "G14": {"cue": "be called", "key": ["being called"], "also": [], "rule": "In 'get used to' the word 'to' is a preposition, so the gerund follows; Walter is the one called a hero, so the passive gerund is needed.", "page": "Reader p. 12"}, "G15": {"cue": "lose", "key": ["to have lost"], "also": [], "rule": "'appear' (= seem) takes the to-infinitive; the perfect infinitive is required because the statement covers the whole period up to now (= it has lost none of its charm).", "page": "Reader p. 7"}}}, {"id": "tense", "title": "Tense & aspect", "short": "Tense", "kind": "type", "width": "", "instruction": "Read the text carefully, taking the whole context into account, and fill in the correct verb form (correct tense and correct aspect). Adjust the word order where necessary.", "paras": ["St Aldric’s College in the north of England {{G1}} home to a ghost for as long as anyone can remember. Even today, many first-year students {{G2}} that a phantom pianist plays Chopin in Hartley Hall after midnight. I know better, because in November 1994 I solved the mystery together with a friend – no, on second thoughts, I {{G3}} him here, since he is now a very serious judge.", "My friend and I both had jobs as night porters, and late one night that November we {{G4}} the post in the lodge when the music began. It came from the music room, which the caretaker {{G5}} two hours earlier. We {{G6}} across the courtyard, but the moment we touched the door, the music stopped. Neither of us suspected that the answer {{G7}} the whole college.", "“I made up my mind last night,” I told my friend the next morning. “Tonight I {{G8}} behind the curtains in the music room.” At midnight the door creaked open, and a small grey-haired woman in a cleaner’s overall {{G9}} in. It was Mrs Dobbs, who cleaned our corridors every morning. She sat down at the piano and began to play. When I stepped out from behind the curtain, she jumped.", "“Don’t look at me as if I {{G10}} a ghost, young man,” she said.", "“Where {{G11}} to play like that?” I asked. She explained that she had studied music in London as a girl, and she confessed that she {{G12}} that old piano ever since her first day at the college.", "“The college Christmas concert {{G13}} at seven on Friday,” I said. “If you play there, the whole college {{G14}} you.”", "“Oh, you {{G15}} silly – you’re usually such a sensible young man,” she laughed. “If I {{G16}} any real talent, I wouldn’t be cleaning corridors for a living.”", "“When you {{G17}} the first round of applause on Friday, you’ll forget your nerves,” I promised.", "She did play, and she received a standing ovation. If I {{G18}} behind that curtain, the college {{G19}} its phantom pianist. Mrs Dobbs is in her nineties now, and she {{G20}} a grand piano of her own, a gift from her many admirers."], "gaps": {"G1": {"cue": "to be", "key": ["has been"], "also": [], "rule": "“For as long as anyone can remember” + present frame = continuative present perfect; “be” is a state verb, so no progressive.", "page": "Reader pp. 14–15"}, "G2": {"cue": "to firmly believe", "key": ["firmly believe"], "also": [], "rule": "Narrator’s present (“Even today”): “believe” is a state verb of inert cognition → simple present; the adverb goes in mid-position before the simple verb.", "page": "Reader pp. 14, 34–35"}, "G3": {"cue": "not to name", "key": ["won't name", "will not name", "shan't name", "shall not name"], "also": [], "rule": "The narrator decides at the moment of telling not to name him (“here”) – negative will/shall-future for a spontaneous decision.", "page": "Reader p. 17"}, "G4": {"cue": "to sort", "key": ["were sorting"], "also": [], "rule": "Time inclusion: the sorting was already in progress (background action) when the music began → past progressive + simple past.", "page": "Reader p. 16"}, "G5": {"cue": "to lock", "key": ["had locked"], "also": [], "rule": "Past perfect for real anteriority: “two hours earlier” places the locking before the past point of orientation (the moment the music began).", "page": "Reader p. 16"}, "G6": {"cue": "to rush", "key": ["rushed"], "also": [], "rule": "Narrative past: the next completed event in the sequence of the story.", "page": "Reader p. 15"}, "G7": {"cue": "to surprise", "key": ["would surprise"], "also": ["was going to surprise", "was to surprise"], "rule": "Future in the past: seen from that night, the later surprise is expressed with would + infinitive (the backshifted future I).", "page": "Reader pp. 17, 19"}, "G8": {"cue": "to hide", "key": ["am going to hide", "'m going to hide"], "also": [], "rule": "“I’ve made up my mind” shows a present intention formed before speaking → going to-future (will would be a spontaneous decision).", "page": "Reader p. 17"}, "G9": {"cue": "to creep", "key": ["crept"], "also": [], "rule": "Narrative past of the irregular verb creep – crept – crept.", "page": "Reader p. 15"}, "G10": {"cue": "to be", "key": ["were"], "also": ["was"], "rule": "Modal past after “as if” (she is not a ghost); in hypothetical meaning “were” is used for all persons.", "page": "Reader pp. 15–16"}, "G11": {"cue": "you to learn", "key": ["did you learn"], "also": [], "rule": "Question about a completed past event → simple past with do-paraphrase: did + subject + infinitive.", "page": "Reader pp. 15, 36–37"}, "G12": {"cue": "to love", "key": ["had loved", "'d loved"], "also": [], "rule": "Reported speech: her present perfect (“I have loved it ever since my first day”) is backshifted to the past perfect after “confessed”; “love” is a state verb, so no progressive.", "page": "Reader pp. 14, 19"}, "G13": {"cue": "to start", "key": ["starts"], "also": [], "rule": "Time-table future: a fixed, scheduled event outside the speaker’s control takes the simple present.", "page": "Reader pp. 14, 17"}, "G14": {"cue": "to adore", "key": ["will adore"], "also": ["is going to adore"], "rule": "Probable condition (pattern I): if-clause in the simple present (“play”), main clause future I.", "page": "Reader p. 18"}, "G15": {"cue": "to be", "key": ["are being", "'re being"], "also": [], "rule": "“Be” + adjective in the progressive = temporary behaviour: the narrator is acting silly at this moment, not by character.", "page": "Reader p. 14"}, "G16": {"cue": "to have", "key": ["had"], "also": ["had had", "'d had"], "rule": "Improbable condition (pattern II), matching “wouldn’t be cleaning”: if-clause in the past; “have” (possession) stays simple. (A mixed conditional with 'had had' is also correct, but the reader's improbable pattern with 'had' is the expected answer.)", "page": "Reader p. 18"}, "G17": {"cue": "to hear", "key": ["hear"], "also": ["have heard", "'ve heard"], "rule": "Temporal sub-clause (when) with future meaning → simple present, never will; “hear” is also a verb of inert perception, so no progressive.", "page": "Reader p. 14"}, "G18": {"cue": "not to hide", "key": ["hadn't hidden", "had not hidden"], "also": [], "rule": "Impossible condition about the past (he did hide): if-clause in the past perfect.", "page": "Reader p. 18"}, "G19": {"cue": "to never discover", "key": ["would never have discovered"], "also": ["would have never discovered"], "rule": "Pattern III main clause: conditional II; with compound verbs “never” normally follows the first auxiliary.", "page": "Reader pp. 18, 34"}, "G20": {"cue": "to own", "key": ["owns"], "also": [], "rule": "Narrator’s present comment (“now”): “own” is a state verb of having → simple present, no progressive.", "page": "Reader p. 14"}}}, {"id": "relatives", "title": "Relative clauses", "short": "Relatives", "kind": "type", "width": "short", "instruction": "Fill in the correct relative pronoun and a comma when necessary. If a contact clause is a correct form, then it must be chosen and indicated by C.", "paras": ["In our family, Thanksgiving has always belonged to my grandmother, Rosa Delgado{{G1}} moved from Santa Fe to Dayton, Ohio, in 1962 and has cooked the holiday dinner every year since. Her apple pie is the one dish {{G2}} nobody else in the family has ever managed to copy. For decades she refused to write the recipe down, so she was the only person {{G3}} knew exactly how much cinnamon went into the filling. My cousins, most {{G4}} are hopeless in the kitchen anyway, gave up trying long ago.", "Last November, however, Grandma sprained her wrist two days before the holiday{{G5}} meant that, for the first time in sixty years, someone else would have to bake the pie. {{G6}} surprised everyone was her choice of assistant: not my mother or one of my aunts, but my nine-year-old brother, Danny.", "The two of them spent the whole afternoon in the same small kitchen {{G7}} she had baked her very first Thanksgiving pie in 1962. Grandma sat on a stool and gave orders, while Danny peeled, sliced and measured, his tongue between his teeth. '{{G8}} you do,' she warned him as he slid the pie into the oven, 'don't open the door before the timer rings.'", "The pie came out slightly lopsided, but at dinner everybody agreed that it tasted exactly like hers, and even Uncle Mike asked for a second slice. And so it was Danny {{G9}} received the little tin box of recipe cards at the end of the evening. Grandma still insists that her secret ingredient was never the cinnamon. 'It's the people {{G10}} you're baking for,' she says."], "gaps": {"G1": {"cue": "", "key": [", who"], "also": [], "rule": "Rosa Delgado is a proper name, so the clause is non-defining (comma); personal antecedent in subject case takes who, and that is impossible in non-defining clauses.", "page": "Reader pp. 27-28"}, "G2": {"cue": "", "key": ["C"], "also": [], "rule": "'the one dish' requires a defining clause, and the pronoun is the object of 'copy' (the subject is 'nobody'), so the zero pronoun is possible and C must be chosen; that/which would lose the point.", "page": "Reader p. 29"}, "G3": {"cue": "", "key": ["who", "that"], "also": [], "rule": "'the only person' requires a defining clause (no comma); personal antecedent in subject case: who or that, and no contact clause because the pronoun is the subject.", "page": "Reader p. 29"}, "G4": {"cue": "", "key": ["of whom"], "also": [], "rule": "Partitive relation in a non-defining clause with a personal antecedent (my cousins): quantifier + of whom ('most of whom'); the comma is already printed before 'most'.", "page": "Reader p. 28"}, "G5": {"cue": "", "key": [", which"], "also": [], "rule": "Connective clause: which refers to the whole preceding clause (the fact that Grandma sprained her wrist), not to 'the holiday', and takes a comma.", "page": "Reader p. 30"}, "G6": {"cue": "", "key": ["What", "what"], "also": [], "rule": "There is no antecedent: what = 'that which / the thing that' and contains its own antecedent (what-clause as subject of 'was').", "page": "Reader p. 30"}, "G7": {"cue": "", "key": ["where", "in which"], "also": [], "rule": "'the same small kitchen' requires a defining clause (no comma); with a place antecedent and no stranded preposition, a contact clause is impossible, so where (= in which, prepositional case) is needed.", "page": "Reader pp. 27, 29"}, "G8": {"cue": "", "key": ["Whatever", "whatever"], "also": ["No matter what"], "rule": "No antecedent and the meaning is 'it doesn't matter what you do': whatever, which acts as object in its own clause and joins it to the main clause (cf. 'Whatever you do, I'll always love you').", "page": "Reader pp. 30-31"}, "G9": {"cue": "", "key": ["who", "that"], "also": [], "rule": "Cleft sentence 'it was ... who': the clause is defining (no comma) and the pronoun is the subject of 'received', so who or that, and no contact clause in subject case.", "page": "Reader p. 29"}, "G10": {"cue": "", "key": ["C"], "also": [], "rule": "Defining clause after 'the people' with the preposition stranded at the end ('baking for'): prepositional case without fronted preposition allows the zero pronoun, so C must be chosen; who/that would lose the point.", "page": "Reader p. 29"}}}, {"id": "mc", "title": "Theory & analysis", "short": "Theory MC", "kind": "mc", "questions": [{"q": "How many of the following sentences contain an INCORRECT non-finite verb form?\n1. My parents made me practise the piano every evening.\n2. The coach suggested to start training earlier in the season.\n3. I would rather stay at home than go to the party.\n4. Our teacher let us to leave ten minutes early.", "opts": ["1", "2", "3", "4"], "ans": 1, "why": "Sentences 2 and 4 are wrong: suggest takes the gerund (suggested starting), and 'let sb do' takes the bare infinitive (let us leave) (Reader pp. 6, 8). Trap: 'make sb do' and 'would rather … than' are correctly followed by the bare infinitive.", "page": "Reader pp. 6, 8"}, {"q": "The garden fence really needs painting. – The gerund 'painting'", "opts": ["is incorrect; after 'need' only the to-infinitive is possible.", "has an active meaning: the fence is going to paint something.", "is incorrect; it should be 'needs to paint'.", "carries a passive meaning (= the fence needs to be painted)."], "ans": 3, "why": "After need, require and deserve, an active gerund has a passive meaning: 'Your hair needs cutting' (Reader p. 12). Trap: 'needs to paint' would mean that the fence itself paints. The correct infinitive alternative is 'needs to be painted'.", "page": "Reader p. 12"}, {"q": "– What are your plans for the weekend? – We're driving up to the Lake District on Saturday; Dad has already booked a cottage. – 'We're driving' expresses", "opts": ["an intention with present arrangement.", "a spontaneous decision.", "a conclusion based on present evidence.", "a time-table future."], "ans": 0, "why": "The present progressive with future meaning is only used for events under the agent's control that are already arranged; here the cottage is booked (Reader p. 17). Trap: the time-table future uses the simple present (The train leaves at …) for events that depend on external circumstances.", "page": "Reader p. 17"}, {"q": "He said to me, 'You must be tired after the long flight.' – According to the reader's rules, which reported version is correct?", "opts": ["He said that I had to be tired after the long flight.", "He said that I must be tired after the long flight.", "He said that I can be tired after the long flight.", "He said that I mustn't be tired after the long flight."], "ans": 1, "why": "must expressing a supposition does not change in reported speech (Reader p. 19). Trap: 'had to' replaces must only when must expresses an obligation (Reader p. 24); here it would turn the guess into a requirement.", "page": "Reader pp. 19, 24"}, {"q": "Which sentence expresses the speaker's annoyance?", "opts": ["My flatmate always leaves the kitchen spotless.", "My flatmate is staying with her parents this week.", "My flatmate is always borrowing my charger without asking.", "My flatmate has always liked old black-and-white films."], "ans": 2, "why": "The present progressive with always/forever expresses the speaker's annoyance (Reader p. 14c: 'You are always laughing at me'). Trap: the simple present with always is a neutral habit, and 'is staying this week' is a temporary state.", "page": "Reader p. 14"}, {"q": "Which modal is used to ask for permission in a very polite and formal way?", "opts": ["can", "had better", "must", "might"], "ans": 3, "why": "might is the very polite and formal permission modal ('Might I have a moment of your time?'), while can is the less formal one (Reader p. 22). Trap: had better gives strong advice and must expresses obligation.", "page": "Reader p. 22"}, {"q": "My brother could have studied medicine, but he decided to become a carpenter. – 'could have studied' expresses", "opts": ["a possibility that may still happen in the future.", "a possibility in the past that was not realised.", "a past ability that he actually used.", "a logical deduction about what he studied."], "ans": 1, "why": "could + perfect infinitive means there was a possibility in the past, but it definitely did not happen (Reader p. 24: 'Max could have married Sam'). Trap: 'could marry/study' without 'have' is a possibility that may still happen, and ability that was actually used is 'was able to'.", "page": "Reader p. 24"}, {"q": "In how many of the following sentences does the modal express a prohibition?\n1. You mustn't feed the animals in the zoo.\n2. You needn't bring a towel – the hotel provides them.\n3. Mobile phones may not be used during the exam.\n4. You can't park in front of the fire station.", "opts": ["1", "2", "3", "4"], "ans": 2, "why": "must not (strong prohibition), may not and cannot (absence of permission, a weaker prohibition) all forbid something (Reader p. 22). Trap: needn't only expresses absence of obligation; you may bring a towel, you just don't have to.", "page": "Reader p. 22"}, {"q": "Which sentence is NOT correct?", "opts": ["We stayed in an old farmhouse, whose roof was covered in moss.", "We stayed in an old farmhouse, the roof of which was covered in moss.", "We stayed in an old farmhouse, which roof was covered in moss.", "We stayed in an old farmhouse, which had a roof covered in moss."], "ans": 2, "why": "For the genitive case with a non-personal antecedent, the reader gives 'whose' or 'the … of which' (Reader p. 28: 'whose history' / 'the history of which'), so 'which roof' is wrong. Trap: 'whose' is not restricted to people.", "page": "Reader p. 28"}, {"q": "In which sentence do you need 'what' (and not 'which' or 'that')?", "opts": ["I couldn't believe ___ the new neighbours had done to their front garden.", "The cake ___ you baked for the party was delicious.", "He forgot my birthday again, ___ really annoyed me.", "The film ___ we saw last night was terribly boring."], "ans": 0, "why": "There is no antecedent, so you need 'what' = 'that which' (the thing that she told me) (Reader p. 30). Trap: after a noun (the cake, the film) or a whole clause (connective clause) you need which/that, never what.", "page": "Reader p. 30"}, {"q": "Which sentence is correct?", "opts": ["Not long after we had moved in, did the neighbours invite us for dinner.", "Not long after we had moved in, had the neighbours invited us for dinner.", "Not long after we had moved in, invited the neighbours us for dinner.", "Not long after we had moved in, the neighbours invited us for dinner."], "ans": 3, "why": "'Not long after' is on the reader's list of expressions that do NOT trigger inversion, like 'not far from', 'no doubt' and 'in no time' (Reader p. 37). Trap: the 'not' looks negative, but only negative or restrictive adverbials such as never, seldom or only require inversion.", "page": "Reader p. 37"}, {"q": "Which sentence shows the normal order of adverbials in end position?", "opts": ["We waited patiently at the bus stop for forty minutes.", "We waited at the bus stop patiently for forty minutes.", "We waited for forty minutes patiently at the bus stop.", "We waited for forty minutes at the bus stop patiently."], "ans": 0, "why": "The normal order is manner – place – time (Reader p. 36: 'We waited patiently outside the theatre all afternoon'). Trap: place comes first only after verbs of motion (I will go to the library by bus tomorrow).", "page": "Reader p. 36"}, {"q": "A wasp stung my little brother on the arm. – Is the definite article before 'arm' correct?", "opts": ["No – parts of the body always take a possessive determiner.", "Yes – in prepositional phrases relating to the object, the definite article is used.", "No – it should be 'an arm', because he has two arms.", "Yes – because 'arm' is a unique noun like 'the earth'."], "ans": 1, "why": "Parts of the body normally take a possessive (He raised his hand), but prepositional phrases related to the object or to the subject of a passive clause take the definite article: 'He hit me in the stomach' (Reader p. 39). Trap: 'always possessive' ignores this exception.", "page": "Reader p. 39"}, {"q": "In which sentence could 'little' be replaced by 'hardly any'?", "opts": ["Would you like a little milk in your tea?", "Little Tommy has just lost his first tooth.", "There is little hope that the old cinema will ever reopen.", "We had a little trouble finding the hotel."], "ans": 2, "why": "'little' without 'a' before an uncountable noun has a negative meaning (= hardly any hope) (Reader p. 40). Trap: 'a little' means a small amount (positive), and in 'Little Tommy' the word is simply an adjective (= small).", "page": "Reader pp. 39–40"}, {"q": "After years of saving, Marco finally opened ___ restaurant in Leeds. – Which version is correct?", "opts": ["an own", "the own", "own", "his own"], "ans": 3, "why": "'own' cannot follow an article, so a possessive determiner has to be added: 'my own car' (Reader p. 40). Trap: German 'ein eigenes Restaurant' tempts learners into 'an own restaurant'; the only other correct option is 'a restaurant of his own'.", "page": "Reader p. 40"}]}]}];
